recipes.integrationExample:
import { calculateGPA, percentageToGrade, discountedPrice } from 'toolnest-core';

const gpa = calculateGPA([
  { gradePoints: 3.8, creditHours: 3 },
  { gradePoints: 3.5, creditHours: 4 },
  { gradePoints: 4.0, creditHours: 3 }
]); // 3.74

const grade = percentageToGrade(88); // 'A'

const scholarship = discountedPrice(150000, 25);
// { discountAmount: 37500, finalPrice: 112500 }

import { convertArea, emiCalculator } from 'toolnest-core';

const areaInMarla = convertArea(10, 'kanal', 'marla'); // 200

const loan = emiCalculator({
  loanAmount: 8000000,
  annualRatePercent: 11,
  tenureMonths: 240
}); // { emi: 82575.07..., totalPayment: ..., totalInterest: ... }

// Rental yield isn't in toolnest-core yet (simple formula, no shared function needed):
const rentalYieldPercent = (480000 / 10000000) * 100; // 4.8

import { percentOf } from 'toolnest-core';

const gst = percentOf(80000, 18); // 14400
const totalInvoice = 80000 + gst; // 94400

// Savings goal isn't in toolnest-core yet (simple division, no shared function needed):
const requiredMonthlySaving = totalInvoice / 12; // 7866.67
